terraform {
  backend "s3" {}
}
module "m" {
  source = "./m"
}
resource "aws_ssm_parameter" "p" {
  name  = "p"
  type  = "String"
  value = module.m.secret
}

terraform {
  backend "s3" {}
}
locals {
  mode = sensitive("public")
}
resource "aws_security_group_rule" "s" {
  type              = "ingress"
  security_group_id = "sg-1"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [local.mode == "public" ? "0.0.0.0/0" : "10.0.0.0/8"]
}

terraform {
  backend "s3" {}
}
data "aws_iam_policy_document" "d" {
  source_policy_documents = [sensitive(jsonencode({ Statement = [{ Effect = "Allow", Action = "*", Resource = "*" }] }))]
}
resource "aws_iam_policy" "p" {
  name   = "p"
  policy = data.aws_iam_policy_document.d.json
}

terraform {
  backend "s3" {}
}
resource "aws_db_instance" "db" {
  identifier = "db"
}
resource "aws_ssm_parameter" "p" {
  name  = "p"
  type  = "String"
  value = sensitive("postgres://app:hunter2@${aws_db_instance.db.address}/app")
}

terraform {
  backend "s3" {}
}
locals {
  m = { a = 1 }
}
resource "aws_sqs_queue" "q" {
  name = "q"
  tags = { x = local.m[sensitive("hunter2")] }
}

