terraform {
  backend "s3" {}
}
variable "partner" {
  sensitive = true
  default   = "123456789012"
}
resource "aws_s3_bucket" "b" {
  bucket = "b"
}
resource "aws_s3_bucket_policy" "p" {
  bucket = aws_s3_bucket.b.id
  policy = jsonencode({ Statement = [
    { Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "${aws_s3_bucket.b.arn}/*" },
    { Effect = "Allow", Principal = { AWS = "arn:aws:iam::${var.partner}:root" }, Action = "s3:ListBucket", Resource = aws_s3_bucket.b.arn },
  ] })
}

terraform {
  backend "s3" {}
}
variable "cidrs" {
  type      = list(string)
  sensitive = true
  default   = ["0.0.0.0/0"]
}
resource "aws_security_group_rule" "s" {
  type              = "ingress"
  security_group_id = "sg-1"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [for c in var.cidrs : c]
}

terraform {
  backend "s3" {}
}
resource "aws_security_group_rule" "s" {
  type              = "ingress"
  security_group_id = "sg-1"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [for c in sensitive(["0.0.0.0/0"]) : c]
}

terraform {
  backend "s3" {}
}
variable "names" {
  sensitive = true
  default   = ["hunter2"]
}
resource "aws_sqs_queue" "q" {
  name = "q"
  tags = { t = "%{for n in var.names}${n}%{endfor}" }
}

terraform {
  backend "s3" {}
}
resource "aws_ecs_task_definition" "api" {
  family                = "api"
  container_definitions = sensitive(jsonencode([{ name = "api", image = "x" }]))
}
resource "aws_security_group_rule" "api" {
